/** HTTP contract for the isolated consumables template/import seam. */
public final class OwnedConsumablesImportExportHttpContractTest {
    private static int checks;
    private static void check(boolean value, String label) { checks++; if (!value) throw new AssertionError(label); }
    public static void main(String[] args) throws Exception {
        Properties properties = new Properties(); try (FileInputStream in = new FileInputStream(args[0])) { properties.load(in); }
        String mode = args.length > 1 ? args[1] : "isolated";
        boolean isolated = "isolated".equalsIgnoreCase(mode);
        Path root = Files.createTempDirectory("owned-consumable-import-export-"); Path audit = root.resolve("audit.jsonl");
        org.springframework.context.ConfigurableApplicationContext app = null;
        try {
            app = start(properties,audit,isolated ? "isolated" : null); DataSource source=app.getBean(DataSource.class); seed(source); int port=port(app);
            String key=http(port,"GET","/open/security/public-key",null,null,null,200).body; String encrypted=encrypt(key,"secret"); String cookie=http(port,"POST","/core/module/sys/login","id=allowed&password="+encrypted,null,key,"application/x-www-form-urlencoded",200).cookie;
            if (!isolated) {
                http(port,"GET","/owned/consumables/import-export-available",null,cookie,null,403);
                http(port,"GET","/core/module/item/files/emcConsumeExportTemplate/action/download-template/emcConsumeExportTemplate",null,cookie,null,403);
                multipart(port,"POST","/core/module/item/files/upload-default/action/import/emcConsumeImportFileFunction",workbook(new String[][]{{"1","P-DENIED","Denied","box","1","Shelf","vendor"}}),cookie,403);
                try(Connection c=source.getConnection();Statement s=c.createStatement();java.sql.ResultSet r=s.executeQuery("SELECT COUNT(1) FROM T_EMC_CONSUME WHERE PRODUCTNO='P-DENIED'")){r.next();check(r.getInt(1)==0,"default mode writes no material");}
                System.out.println("consumable import/export default mode: PASS ("+checks+" checks; write routes denied)");
                return;
            }
            Reply available=http(port,"GET","/owned/consumables/import-export-available",null,cookie,null,200);
            check(available.body.contains("\"available\":true"),"import/export capability is available");
            Reply template=http(port,"GET","/core/module/item/files/emcConsumeExportTemplate/action/download-template/emcConsumeExportTemplate",null,cookie,null,200);
            check(template.bodyBytes.length>100,"template has bytes"); check(template.contentType != null && template.contentType.contains("application/vnd.ms-excel"),"template content type");
            byte[] workbook = workbook(new String[][]{{"1","P-NEW","New material","10 ml","5","Shelf A","vendor-a"},{"2","P-OLD","Existing material","1 ml","7","Shelf B","vendor-b"}});
            Reply imported = multipart(port,"POST","/core/module/item/files/upload-1/action/import/emcConsumeImportFileFunction",workbook,cookie,200);
            check(imported.body.contains("\"rows\":2"),"import reports two rows");
            try(Connection c=source.getConnection();Statement s=c.createStatement();java.sql.ResultSet r=s.executeQuery("SELECT COUNT(1) FROM T_EMC_CONSUME WHERE PRODUCTNO IN ('P-NEW','P-OLD')")){r.next();check(r.getInt(1)==2,"import writes material rows");}
            try(Connection c=source.getConnection();Statement s=c.createStatement();java.sql.ResultSet r=s.executeQuery("SELECT COUNT(1) FROM T_EMC_CSM_STOCK WHERE MTLID IN (SELECT ID FROM T_EMC_CONSUME WHERE PRODUCTNO IN ('P-NEW','P-OLD'))")){r.next();check(r.getInt(1)==2,"import writes stock rows");}
            try(Connection c=source.getConnection();Statement s=c.createStatement();java.sql.ResultSet r=s.executeQuery("SELECT COUNT(1) FROM T_EMC_CONSUME WHERE (PRODUCTNO='P-NEW' AND STOCKQTY=5) OR (PRODUCTNO='P-OLD' AND STOCKQTY=7)")){r.next();check(r.getInt(1)==2,"import updates material aggregate stock");}
            multipart(port,"POST","/core/module/item/files/upload-blank/action/import/emcConsumeImportFileFunction",workbook(new String[][]{{"1","P-NEW","New material metadata","10 ml","","",""},{"2","P-EMPTY","Material without stock","box","","",""}}),cookie,200);
            try(Connection c=source.getConnection();Statement s=c.createStatement();java.sql.ResultSet r=s.executeQuery("SELECT COUNT(1) FROM T_EMC_CSM_STOCK WHERE MTLID=(SELECT ID FROM T_EMC_CONSUME WHERE PRODUCTNO='P-NEW') AND STOCKQTY=5")){r.next();check(r.getInt(1)==1,"blank stock preserves existing stock quantity");}
            try(Connection c=source.getConnection();Statement s=c.createStatement();java.sql.ResultSet r=s.executeQuery("SELECT COUNT(1) FROM T_EMC_CONSUME C WHERE C.PRODUCTNO='P-EMPTY' AND NOT EXISTS (SELECT 1 FROM T_EMC_CSM_STOCK S WHERE S.MTLID=C.ID)")){r.next();check(r.getInt(1)==1,"blank stock creates material without a stock row");}
            byte[] invalid=workbook(new String[][]{{"1","P-BAD","","bad","-1","Shelf","vendor"}});
            multipart(port,"POST","/core/module/item/files/upload-2/action/import/emcConsumeImportFileFunction",invalid,cookie,400);
            try(Connection c=source.getConnection();Statement s=c.createStatement();java.sql.ResultSet r=s.executeQuery("SELECT COUNT(1) FROM T_EMC_CONSUME WHERE PRODUCTNO='P-BAD'")){r.next();check(r.getInt(1)==0,"invalid import rolls back");}
            String low=http(port,"POST","/core/module/sys/login","id=low&password="+encrypted,null,key,"application/x-www-form-urlencoded",200).cookie;
            http(port,"GET","/owned/consumables/import-export-available",null,low,null,403);
            http(port,"GET","/core/module/item/files/emcConsumeExportTemplate/action/download-template/emcConsumeExportTemplate",null,low,null,403);
            multipart(port,"POST","/core/module/item/files/upload-low/action/import/emcConsumeImportFileFunction",workbook(new String[][]{{"1","P-DENIED","Denied","box","1","Shelf","vendor"}}),low,403);
            String records=new String(Files.readAllBytes(audit),StandardCharsets.UTF_8); check(records.contains("consumable-template-export")&&records.contains("consumable-import"),"import/export audited"); check(!records.contains("secret"),"audit omits password");
        } finally { if(app!=null)app.close(); Files.walk(root).sorted(Comparator.reverseOrder()).forEach(p->{try{Files.deleteIfExists(p);}catch(IOException e){throw new java.io.UncheckedIOException(e);}}); }
        System.out.println("consumable import/export: PASS ("+checks+" checks; isolated Oracle loopback only)");
    }
    private static org.springframework.context.ConfigurableApplicationContext start(Properties p,Path audit,String mode){java.util.List<String>a=new java.util.ArrayList<String>();a.add("--server.address=127.0.0.1");a.add("--server.port=0");a.add("--spring.config.name=owned-consumable-write-test");a.add("--spring.main.banner-mode=off");a.add("--spring.main.log-startup-info=false");a.add("--spring.autoconfigure.exclude=org.springframework.boot.autoconfigure.security.servlet.SecurityAutoConfiguration");a.add("--spring.datasource.type=org.springframework.jdbc.datasource.DriverManagerDataSource");a.add("--spring.datasource.driver-class-name=oracle.jdbc.OracleDriver");a.add("--spring.datasource.url="+p.getProperty("url"));a.add("--spring.datasource.username="+p.getProperty("user"));a.add("--spring.datasource.password="+p.getProperty("password"));a.add("--sunway.user.password.encoder.type=MD5");a.add("--owned.identity.audit.type=file");a.add("--owned.identity.audit.path="+audit.toAbsolutePath());if(mode!=null)a.add("--owned.consumables.import-export.mode="+mode);com.sunwayworld.emc.projectfunction.GikamWpjcApplication.main(a.toArray(new String[0]));return com.sunwayworld.owned.internal.context.OwnedApplicationContext.getApplicationContext();}
    private static int port(org.springframework.context.ConfigurableApplicationContext app){return ((org.springframework.boot.web.servlet.context.ServletWebServerApplicationContext)app).getWebServer().getPort();}
    private static void seed(DataSource d)throws SQLException{try(Connection c=d.getConnection();Statement s=c.createStatement()){s.execute("CREATE TABLE T_CORE_USER (ID VARCHAR2(64) PRIMARY KEY, USERNAME VARCHAR2(100), PASSWORD VARCHAR2(120), ORGID VARCHAR2(64), ORGNAME VARCHAR2(100), STATUS VARCHAR2(20), LASTSUSPENDEDFLAG VARCHAR2(1), EXPIRYDATE TIMESTAMP, PARENTORGID VARCHAR2(64))");s.execute("CREATE TABLE T_CORE_ROLE (ID NUMBER PRIMARY KEY,LASTSUSPENDEDFLAG VARCHAR2(1))");s.execute("CREATE TABLE T_CORE_ROLE_USER (ROLEID NUMBER,USERID VARCHAR2(64))");s.execute("CREATE TABLE T_CORE_ROLE_PERMISSION (ROLEID NUMBER,PERMISSIONTYPEID VARCHAR2(64),TARGETID VARCHAR2(64))");s.execute("CREATE TABLE T_CORE_MENU (ID VARCHAR2(64) PRIMARY KEY)");s.execute("CREATE TABLE T_CORE_ORG (ID VARCHAR2(64) PRIMARY KEY,ORGNAME VARCHAR2(100))");s.execute("CREATE TABLE T_CORE_USER_PERMISSION (USERID VARCHAR2(64),PERMISSIONTYPEID VARCHAR2(64),TARGETID VARCHAR2(64))");s.execute("CREATE TABLE T_CORE_LOGIN_CONFIG (ID VARCHAR2(64) PRIMARY KEY,LOGINORG VARCHAR2(1),LOGINROLE VARCHAR2(1),LOGINTENANT VARCHAR2(1),LOGINAUTHMETHOD VARCHAR2(36),CAPTCHA VARCHAR2(1),ADDOMAINSUPPORT VARCHAR2(1),SHOWLOGINAUTHOPTION VARCHAR2(1),QCCODE VARCHAR2(1))");s.execute("INSERT INTO T_CORE_LOGIN_CONFIG VALUES ('login-config','0','0',NULL,'system','0','0','0','0')");s.execute("CREATE TABLE T_CORE_PASSWORD_POLICY (ID NUMBER PRIMARY KEY,MAXFAILEDATTEMPTS NUMBER,EXPIRYINTERVAL NUMBER,EXPIREDPOLICY VARCHAR2(36),LASTSUSPENDEDFLAG VARCHAR2(1))");s.execute("INSERT INTO T_CORE_PASSWORD_POLICY VALUES (1,0,0,'optional','0')");s.execute("CREATE TABLE T_EMC_CONSUME (ID VARCHAR2(64) PRIMARY KEY,MTLNAME VARCHAR2(100),SPECIFICATION VARCHAR2(100),STOCKQTY NUMBER,MTLCATEGORYID VARCHAR2(64),HARMFULNESS VARCHAR2(36),PRODUCTNO VARCHAR2(64),CREATEDBYID VARCHAR2(64),CREATEDBYNAME VARCHAR2(100),CREATEDTIME TIMESTAMP,CREATEDBYORGID VARCHAR2(64),CREATEDBYORGNAME VARCHAR2(100))");s.execute("CREATE TABLE T_EMC_CSM_STOCK (ID NUMBER PRIMARY KEY,MTLID VARCHAR2(64),BATCHNO VARCHAR2(100),STOCKQTY NUMBER,UNITNAME VARCHAR2(64),EXPIREDATE DATE,LOWLIMIT NUMBER,STATUS VARCHAR2(1),CREATEDBYID VARCHAR2(64),CREATEDBYNAME VARCHAR2(100),CREATEDTIME TIMESTAMP,CREATEDBYORGID VARCHAR2(64),CREATEDBYORGNAME VARCHAR2(100))");s.execute("CREATE TABLE T_EMC_CSM_STOCK_LOG (ID NUMBER PRIMARY KEY,STOCKID NUMBER,LOGTYPE VARCHAR2(20),PREVIOUSQTY NUMBER,QTY NUMBER,VENDORID VARCHAR2(64),PRICE NUMBER,LOGCONTENT VARCHAR2(200),RECEIVEDBYID VARCHAR2(64),RECEIVEDBYORGID VARCHAR2(64),CREATEDBYID VARCHAR2(64),CREATEDBYNAME VARCHAR2(100),CREATEDTIME TIMESTAMP,CREATEDBYORGID VARCHAR2(64),CREATEDBYORGNAME VARCHAR2(100))");s.execute("CREATE SEQUENCE SEQ_CORE START WITH 1000 INCREMENT BY 1");s.execute("INSERT INTO T_CORE_MENU VALUES ('430201')");s.execute("INSERT INTO T_CORE_ORG VALUES ('org-a','Fixture Org A')");s.execute("INSERT INTO T_CORE_USER VALUES ('allowed','Allowed User','5ebe2294ecd0e0f08eab7690d2a6ee69','org-a','Fixture Org A','activated','0',NULL,'org-a')");s.execute("INSERT INTO T_CORE_USER VALUES ('low','Low User','5ebe2294ecd0e0f08eab7690d2a6ee69','org-a','Fixture Org A','activated','0',NULL,'org-a')");s.execute("INSERT INTO T_CORE_ROLE VALUES (1,'0')");s.execute("INSERT INTO T_CORE_ROLE_USER VALUES (1,'allowed')");s.execute("INSERT INTO T_CORE_ROLE_PERMISSION VALUES (1,'T_CORE_MENU','430201')");s.execute("INSERT INTO T_CORE_USER_PERMISSION VALUES ('allowed','T_CORE_ORG','org-a')");s.execute("INSERT INTO T_EMC_CONSUME VALUES ('m-old','Existing material','1 ml',1,NULL,NULL,'P-OLD','allowed','Allowed User',SYSTIMESTAMP,'org-a','Fixture Org A')");}}
    private static byte[] workbook(String[][] rows)throws Exception{HSSFWorkbook w=new HSSFWorkbook();org.apache.poi.hssf.usermodel.HSSFSheet s=w.createSheet();s.createRow(0).createCell(0).setCellValue("耗材导入模版");String[] h={"序号","货号","材料名称","规格型号","库存","存放位置","供应商"};org.apache.poi.hssf.usermodel.HSSFRow header=s.createRow(1);for(int i=0;i<h.length;i++)header.createCell(i).setCellValue(h[i]);for(int r=0;r<rows.length;r++){org.apache.poi.hssf.usermodel.HSSFRow row=s.createRow(r+2);for(int c=0;c<rows[r].length;c++)row.createCell(c).setCellValue(rows[r][c]);}ByteArrayOutputStream out=new ByteArrayOutputStream();w.write(out);w.close();return out.toByteArray();}
    private static String encrypt(String key,String plain)throws Exception{Cipher c=Cipher.getInstance("RSA/ECB/PKCS1Padding");PublicKey k=KeyFactory.getInstance("RSA").generatePublic(new X509EncodedKeySpec(Base64.getDecoder().decode(key)));c.init(Cipher.ENCRYPT_MODE,k);return URLEncoder.encode(Base64.getEncoder().encodeToString(c.doFinal(plain.getBytes(StandardCharsets.UTF_8))),"UTF-8");}
    private static Reply http(int port,String method,String path,String body,String cookie,String key,int expected)throws Exception{return http(port,method,path,body,cookie,key,null,expected);}
    private static Reply http(int port,String method,String path,String body,String cookie,String key,String type,int expected)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL("http://127.0.0.1:"+port+path).openConnection();c.setRequestMethod(method);c.setConnectTimeout(5000);c.setReadTimeout(10000);if(cookie!=null)c.setRequestProperty("Cookie",cookie);if(key!=null)c.setRequestProperty("SECURITY-RSA-KEY",key);if(body!=null){c.setDoOutput(true);c.setRequestProperty("Content-Type",type==null?"application/json":type);c.getOutputStream().write(body.getBytes(StandardCharsets.UTF_8));}int status=c.getResponseCode();java.io.InputStream in=status>=400?c.getErrorStream():c.getInputStream();byte[] bytes=in==null?new byte[0]:read(in);check(status==expected,method+" "+path+" expected="+expected+" actual="+status+" body="+new String(bytes,StandardCharsets.UTF_8));String set=c.getHeaderField("Set-Cookie");return new Reply(new String(bytes,StandardCharsets.UTF_8),bytes,c.getHeaderField("Content-Type"),set==null?cookie:set.split(";",2)[0]);}
    private static Reply multipart(int port,String method,String path,byte[] data,String cookie,int expected)throws Exception{String boundary="----owned"+System.nanoTime();HttpURLConnection c=(HttpURLConnection)new URL("http://127.0.0.1:"+port+path).openConnection();c.setRequestMethod(method);c.setDoOutput(true);c.setRequestProperty("Cookie",cookie);c.setRequestProperty("Content-Type","multipart/form-data; boundary="+boundary);ByteArrayOutputStream out=new ByteArrayOutputStream();out.write(("--"+boundary+"\r\nContent-Disposition: form-data; name=\"file\"; filename=\"import.xls\"\r\nContent-Type: application/vnd.ms-excel\r\n\r\n").getBytes(StandardCharsets.UTF_8));out.write(data);out.write(("\r\n--"+boundary+"--\r\n").getBytes(StandardCharsets.UTF_8));c.getOutputStream().write(out.toByteArray());int status=c.getResponseCode();java.io.InputStream in=status>=400?c.getErrorStream():c.getInputStream();byte[] bytes=in==null?new byte[0]:read(in);check(status==expected,"multipart expected="+expected+" actual="+status+" body="+new String(bytes,StandardCharsets.UTF_8));return new Reply(new String(bytes,StandardCharsets.UTF_8),bytes,c.getHeaderField("Content-Type"),cookie);}
    private static byte[] read(java.io.InputStream in)throws IOException{ByteArrayOutputStream o=new ByteArrayOutputStream();byte[] b=new byte[4096];for(int n;(n=in.read(b))!=-1;)o.write(b,0,n);return o.toByteArray();}
    private static final class Reply{final String body;final byte[] bodyBytes;final String contentType,cookie;Reply(String b,byte[] bb,String ct,String c){body=b;bodyBytes=bb;contentType=ct;cookie=c;}}
}
